#[derive(Clone, PartialEq, Eq, PartialOrd, Ord)]
enum Value {
    Null,
    Int(i64),
    Text(String),
}
impl Value {
    fn text(&self) -> String {
        match self {
            Self::Null => "NULL".into(),
            Self::Int(n) => n.to_string(),
            Self::Text(s) => s.clone(),
        }
    }
    fn truth(&self) -> Option<bool> {
        match self {
            Self::Int(n) => Some(*n != 0),
            _ => None,
        }
    }
    fn ty(&self) -> u8 {
        match self {
            Self::Null => 0,
            Self::Int(_) => 1,
            Self::Text(_) => 2,
        }
    }
}
